Replaced the linear scan with a lazily built 65,536-entry index table that stores the first matching message index plus one, making each lookup O(1) while preserving first-match and `NULL` behavior. The table is built once with only `MESGS` writes, so repeated lookups and full-domain sweeps are much faster.

```cpp
const Profile::MESG* Profile::GetMesg(const FIT_UINT16 num)
{
    static FIT_UINT16 lookup[65536];
    static bool initialized = false;

    if (!initialized)
    {
        for (int i = 0; i < MESGS; i++)
        {
            const FIT_UINT16 n = mesgs[i].num;
            if (lookup[n] == 0)
                lookup[n] = static_cast<FIT_UINT16>(i + 1);
        }
        initialized = true;
    }

    const FIT_UINT16 idx = lookup[num];
    if (idx != 0)
        return &mesgs[idx - 1];

    return NULL;
}
```

